contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking an amount to send with the play call
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read pre-call observable state
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        // perform the state-changing call and capture whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read post-call observable state
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General rule: if call reverted, nothing observable changed; otherwise bank unchanged and
        // pot is either potBefore + TICKET_AMOUNT (when contract kept the ticket) or 0 (when payout happened),
        // and contract balance changed consistently with pot change (i.e., balAfter >= potAfter).
        // We cannot refer to constants inside C directly, so express allowed pot changes relative to amount.
        // When call succeeds, the only permitted increases to pot are exactly by amount (the ticket) or reset to 0.

        assert(
            // if reverted: all observables unchanged
            (reverted && bankAfter == bankBefore && potAfter == potBefore && balAfter == balBefore)
            ||
            // if not reverted: bank unchanged, and pot either increased by amount or became 0, and contract balance at least potAfter
            (!reverted && bankAfter == bankBefore && (potAfter == potBefore + amount || potAfter == 0) && balAfter >= potAfter)
        );
    }

    // allow receiving Ether when C sends payouts to this test contract
    receive() external payable {}
}

