// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        address bankBefore;
        try c.bank() returns (address __r) { bankBefore = __r; } catch { return; }
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address bankAfter;
        try c.bank() returns (address __r) { bankAfter = __r; } catch { return; }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue((reverted && bankAfter == bankBefore && potAfter == potBefore && balAfter == balBefore)
            ||
            // if not reverted: bank unchanged, and pot either increased by amount or became 0, and contract balance at least potAfter
            (!reverted && bankAfter == bankBefore && (potAfter == potBefore + amount || potAfter == 0) && balAfter >= potAfter));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
